-- Only saly.*; applied LEG-05/C2 in progress; NO legal permit / no automatic PASS.
BEGIN;
DO $pre$ DECLARE n integer; BEGIN
 IF (SELECT count(*) FROM saly.programas_investigacion p JOIN saly.proyecto z ON z.id=p.proyecto_id WHERE p.codigo='SALY_FONDEO_LEGAL' AND z.codigo='SALY-001')<>1 THEN RAISE EXCEPTION 'BLOCK_SALY_C2_PROGRAM'; END IF;
 IF (SELECT count(*) FROM saly.checkpoints_investigacion c JOIN saly.unidades_investigacion u ON u.id=c.unidad_id
 WHERE u.codigo='SALY-LEG-05' AND c.codigo='C1' AND c.estado='DONE')<>1 THEN RAISE EXCEPTION 'BLOCK_SALY_C2_NO_C1'; END IF;
 IF (SELECT count(*) FROM saly.checkpoints_investigacion c JOIN saly.unidades_investigacion u ON u.id=c.unidad_id
 WHERE u.codigo='SALY-LEG-05' AND c.codigo='C2' AND c.estado='PENDIENTE' AND c.evidencia_principal_id IS NULL)<>1 THEN RAISE EXCEPTION 'BLOCK_SALY_C2_STATUS_DRIFT'; END IF;
 IF EXISTS(SELECT 1 FROM saly.evidencias WHERE codigo='SALY-EVD-LEG-05-C2-AVANCE-20261020') THEN RAISE EXCEPTION 'BLOCK_SALY_C2_EVIDENCE_EXISTS'; END IF;
 IF (SELECT count(*) FROM saly.escenarios WHERE codigo IN ('SALY-ESC-011','SALY-ESC-012','SALY-ESC-013','SALY-ESC-014')
 AND estado='BORRADOR' AND parametros->'evaluacion_legal'->>'estado'='EN_INVESTIGACION'
 AND NOT ((parametros->'evaluacion_legal') ? 'analisis_c2_preliminar'))<>4 THEN RAISE EXCEPTION 'BLOCK_SALY_SCENARIO_STATUS'; END IF;
END $pre$;
INSERT INTO saly.evidencias(codigo,tipo,titulo,descripcion,referencia,fecha_evidencia,hechos,estado)
VALUES('SALY-EVD-LEG-05-C2-AVANCE-20261020','ANALISIS_APLICADO_PRELIMINAR',
 'Comparación de cuatro rutas empresariales y separación adelanto laboral/préstamo',
 'Aplicación C2 preliminar a A SaaS empleador prestamista, B mandato, C cesión inmediata y D línea a SALY. Identifica flujos, contratos, registros, límites, impuestos, responsables y documentos faltantes. No emite exención SBS ni autorización.',
 'Normativa SBS Res650-2024; SUNAT LIR26; TC STC02275-2023; ENAPU politica 2024; CC/LGS/CTS; modelos TuSueldoYa aportados por usuario.',
 DATE '2026-10-20', '{"schema":"saly.c2_aplicado_empresarial/v1","program":"SALY_FONDEO_LEGAL","unit":"SALY-LEG-05","checkpoint":"C2","fecha":"2026-10-20","estado_investigacion":"AVANCE_C2_NO_CIERRE","business_fact":"TuSueldoYa históricamente concede préstamos por convenio y recuperación de planilla; SALY estudia programa con capital exclusivamente del empleador o capital empresarial canalizado por SALY; la rotación mensual no altera la identidad del acreedor.","distinctions":{"salary_advance":"Empleador anticipa remuneracion por prestación laboral, sin presuponer mutuo comercial. Requiere sustancia, devengo y contabilidad laboral.","employer_to_employee_loan":"Mutuo verdadero entre empleador y trabajador; puede ser con o sin intereses segun contrato, con límites laborales, IR art26 solo si los presupuestos se cumplen.","saly_credit_and_employee_debt":"Crédito de SALY a trabajador, aunque descuente empleador; no convertir a adelanto de sueldo laboral con sola etiqueta."},"official_sources":[{"citation":"SBS_650_2024","authority":"SBS","instrument":"Resolucion SBS 650-2024","section":"2.b,3,4,6","url":"https://www.sbs.gob.pe/Portals/0/Archivos/super_registros/Resolucion-SBS-N-650-2024.pdf","proven":"Empresas dedicadas a otorgar prestamos con fondos propios a clientes, incluso via plataforma, deben registrar actividad; registro gratuito e indeterminado; no hay excluyente textual ''solo empleados''."},{"citation":"SUNAT_LIR26_2026","authority":"SUNAT","instrument":"TUO Ley del Impuesto a la Renta","section":"articulo 26","url":"https://www.sunat.gob.pe/legislacion/renta/ley/capv.pdf","proven":"Excepcion presuncion de intereses en ciertos prestamos del empleador a su personal por concepto de adelanto de sueldo que no superen 1 UIT; no es tope general para prestar ni exencion de registro SBS."},{"citation":"ENAPU_PRST_2024","authority":"ENAPU","instrument":"Acuerdo 009/02/2024/D politica prestamos al personal","section":"politica y decision directorio","url":"https://www.enapu.com.pe/sistema-transparencia/views/documentos/1551212393.jj.pdf","proven":"Entidad portuaria no financiera documenta programa interno de prestamos por politica aprobada por directorio; antecedente practico, empresa publica con reglas propias, no salvoconducto para privado."},{"citation":"TC_02275_2023","authority":"Tribunal Constitucional","instrument":"Sentencia 356/2025 caso descuento cooperativas por empleador","section":"fundamentos 3,9,14-17","url":"https://www.tc.gob.pe/jurisprudencia/2025/02275-2023-AA.html","proven":"El consentimiento de descuento no desplaza proteccion del salario ni habilita retenciones abusivas; aplicacion a credito directo del empleador requiere analizar hechos especificos."},{"citation":"CTS_DLEG650","authority":"Congreso","instrument":"Decreto Legislativo 650 Ley CTS","section":"articulos 40-41 y TUO vigente a cotejar","url":"https://www.leyes.congreso.gob.pe/Documentos/DecretosLegislativos/00650.pdf","proven":"CTS reconoce deudas de trabajadores frente a empleadores por determinadas modalidades y garantias sujetas a condiciones y limites; no autoriza descontar indiscriminadamente remuneracion ni CTS."},{"citation":"LGS_11","authority":"Congreso","instrument":"Ley General Sociedades","section":"articulo 11","url":"https://www2.congreso.gob.pe/sicr/cendocbib/con4_uibd.nsf/F192BA67C92F4D5C0525804900719FA2/%24FILE/pe061es.pdf","proven":"Actos vinculados con objeto social y fines legales; no sustituye autorizaciones para actividades reservadas."},{"citation":"CC_1648","authority":"El Peruano","instrument":"Codigo Civil","section":"1648 y 1206-1215","url":"https://diariooficial.elperuano.pe/Normas/obtenerDocumento?idNorma=60","proven":"Mutuo crea obligacion de devolucion; cesion escrita y eficaz frente deudor cuando concurra requisito correspondiente."}],"historical_documents":[{"asset":"TSY Convenio Marco de Prestamos con Descuento por Planilla Working Center.pdf","supported":"Base histórica de convenio donde fintech concede créditos y empleador gestiona descuento/obligaciones; no contrato de autofondeo SaaS."},{"asset":"TSY Adenda Convenio Marco de Prestamos con Descuento por Planilla (04.08.22.VF).docx","supported":"Modelo de autorización cesion de cartera a terceros; borrador no cesion ejecutada."},{"asset":"AUTORIZACION_DE_DESCUENTO74611598_5_05-01-2026-17-24(1).pdf","supported":"Evidencia de aceptación digital del descuento; datos personales excluidos y limites deben revisarse."}],"comparacion":[{"escenario":"SALY-ESC-011","modelo":"A","nombre":"Empresa prestamista y SALY SaaS","funds":"CAPITAL_PROPIO_EMPRESA -> DESEMBOLSO_INSTRUCCION_EMPLEADOR -> TRABAJADOR","origin":"EMPLEADOR","creditor":"EMPLEADOR","collector":"EMPLEADOR (planilla) con SALY tecnologia","saly":"SaaS licencia, motor, expediente, onboarding, instruccion bancaria sin custodiar recursos","income":{"employer":"intereses o cargos crediticios solo si proceden","saly":"licencia y servicios SaaS"},"operational_requirements":["Aprobacion politica de prestamos del empleador y facultades societarias","Prestamo trabajador-empresa; consentimiento informado y autorizacion de descuentos dentro de limites","Fondos y titulos crediticios a nombre de empresa; cuenta bancaria empleador o agente de pagos autorizado","Contrato de servicio SALY sin simulacion de que SALY sea acreedor; datos personales y responsabilidades","Clasificar con SBS si actividad interna accesoria o ''dedicada'' a prestamos registrados, segun operativa real"],"legal_position":"FIGURA_CIVIL_PLAUSIBLE_CONDICIONADA_A_CLASIFICACION_DE_ACTIVIDAD_Y_PLANILLA","permitted_without_fund":"NO_REQUIERE_FONDO_POR_SU_SOLO_USO_DE_CAJA","registration":"NO_DETERMINADO_ESPONSABILIDAD_REAL","tax":"Articulo 26 solo condicion especifica adelanto sueldo hasta UIT, no todo prestamo personal, interest real e IGV SaaS requieren tributacion por actor","fallback":"Analizar C o D si actividad interna constituye prestamista regulado que empleador no acepta","complexity":"MENOR_OPERATIVA_POTENCIAL_SIN_CESION"},{"escenario":"SALY-ESC-012","modelo":"B","nombre":"Bolsa empleador administrada por SALY bajo mandato","funds":"CAPITAL_PROPIO_EMPRESA -> CUENTA_DIFERENCIADA -> DESEMBOLSO_TRABAJADOR","origin":"EMPLEADOR","creditor":"EMPLEADOR","collector":"EMPLEADOR_COBRANZA_PLANILLA","saly":"SaaS + mandato operacional, potencial custodia o pago por cuenta ajena","income":{"employer":"credito trabajador","saly":"tecnologia y administracion"},"operational_requirements":["Precisar nombre legal de cuenta, propiedad, segregacion y disponibilidad","Acreditar mandato y responsabilidades si SALY opera instrumentos bancarios, custodia y administracion","Separar instruccion tecnica y disposicion de recursos ajenos","Mismas obligaciones laborales y SBS potenciales del prestamista empleador"],"legal_position":"CONDICIONADO_POR_REGIMEN_DE_GESTION_DE_DINERO_DE_TERCEROS","registration":"NO_DETERMINADO_CUSTODIA_Y_PRESTAMOS","tax":"Servicios adicionales de mandato, IGV, posibles cargos bancarios; no atribuir rendimientos a SALY por administrar caja","fallback":"Mantener A con cuenta empleador y SALY solo instrucciones validadas","complexity":"MAS_ALTA_POR_GESTION_DE_DINERO"},{"escenario":"SALY-ESC-013","modelo":"C","nombre":"SALY presta y cede contemporaneamente a empleador","funds":"EMPRESA COMPRA CRÉDITO AL NACER, SALY ORIGINA PRÉSTAMO","origin":"SALY","creditor":"EMPLEADOR DESPUES DE CESION VALIDA","collector":"EMPRESA PLANILLA O SALY COMO SERVICER","saly":"Originacion de credito y cesion, software y administracion","income":{"employer":"recuperacion cartera y rendimiento comprado","saly":"precio cesion, costos originacion/servicing"},"operational_requirements":["Contrato de credito SALY-trabajador, contrato marco cesion futura por escrito","Aceptacion/comunicacion fehaciente de cesion y trazabilidad de titularidad exacta","Demostrar SALY propietaria inicial antes de ceder y cesionario empleador con potestades","Evaluar registro SBS de SALY prestamista habitual y comprador empleador separado","Precio, descuento, riesgo de incobrabilidad, recompra y contabilidad"],"legal_position":"CESION_CIVIL_PLAUSIBLE_SIN_SAFI_PERO_CON_FORMALIDADES_Y_CLASIFICACION_DE_ACTIVIDAD","registration":"NO_DETERMINADO_POR_DOS_ACTORES","tax":"Ingreso por cesion y ganancia de cartera son distintos al SaaS; no asumir neutralidad del IGV de todos conceptos","fallback":"Si empresa no quiere comprar credito/cesiones frecuentes, elegir A o D","complexity":"ALTA_CESION_POR_CREDITO"},{"escenario":"SALY-ESC-014","modelo":"D","nombre":"Empresa otorga linea revolvente a SALY; SALY presta","funds":"EMPRESA PRESTA A SALY -> SALY DESEMBOLSA -> TRABAJADOR","origin":"SALY","creditor":"SALY","collector":"EMPLEADOR POR CONVENIO PLANILLA A FAVOR SALY","saly":"Prestamista al trabajador y gestor","income":{"employer":"rendimiento linea empresaria SALY","saly":"intereses/cargos de trabajador netos de fondeo"},"operational_requirements":["Prestamo empresa-SALY y contrato por separado SALY-trabajador","Evaluar si empresa se dedica realmente a prestar dinero aunque receptor sea una sola entidad","Registro SBS correspondiente a SALY si actividad de prestamos le es aplicable","Lineas circulantes limites, vencimientos, cartera, inversion en riesgo, garantia","Descuento por planilla con autorizacion laboral"],"legal_position":"DOS_MUTUOS_POSIBLES_CON_RIESGO_REGULATORIO_Y_FINANCIERO_EN_AMBOS_EXTREMOS","registration":"NO_DETERMINADO_AMBOS_PRESTAMISTAS","tax":"Intereses de linea empresa-SALY y margen a trabajador; no aplicar la excepcion 1 UIT del trabajador al prestamo B2B","fallback":"Si registro empresarial o doble carga excesiva, preferir A o comprador fondo E","complexity":"MAYOR_RIESGO_SALY"}],"decision_preliminar":{"rutas_priorizadas":["SALY-ESC-011","SALY-ESC-013","SALY-ESC-014","SALY-ESC-012"],"razon":"A elimina cesiones y potencial custodia, pero no evita obligaciones del prestamista empleador. Comparar juridicamente costo registro/compliance.","permiso_final":false,"apto_final":false},"regulatory_gap_sbs":"Resolución SBS 650-2024 define empresa DEDICADA a prestar con fondos propios, sin umbral cuantitativo ni excepción textual empleados. Requiere pronunciamiento interpretativo SBS/UIF o sustento jurídico específico para el empleador y operativa real; precedentes ENAPU no sustituyen clasificación.","labor_risk":"TC 02275-2023 trató descuento a cooperativas de terceros; distingue de crédito directo del empleador y exige revisar aplicación concreta de protección salarial, CTS, alimentos y liquidaciones.","tax_risk":"Artículo 26 LIR tiene excepción puntual a presunción de intereses para adelanto de sueldo <= 1 UIT y otros supuestos; no techo al capital prestado ni habilitacion para llamar adelanto a cualquier préstamo.","registration_cost":{"sbs_registro_pen":0,"source":"Res SBS 650-2024 articulo 6","costo_operativo_compliance_pen":null,"contabilidad_compliance_pen":null,"honorarios_juridicos_pen":null},"needed_to_conclude":["Estatuto y poderes de empleador concreto, giro real y aprobacion de politica crediticia interna.","Flujos de desembolso, propiedad cuenta, facultades SALY y numero/transacciones de trabajadores para analizar DEDICACION SBS.","Interpretación SBS/UIF o dictamen legal sobre actividad accesoria interna versus empresa dedicada a préstamos.","Contratos trabajador-empleador y SALY SaaS, consentimiento concreto, límites de descuento, liquidación y conflictos de interés.","Cuadro de responsabilidades, costos de controles UIF/LAFT/privacidad e IR/IGV por persona.","Revisión independiente C3; este avance NO acredita APTO y no autoriza operación."]}'::jsonb,'VIGENTE');
INSERT INTO saly.checkpoint_evidencias(checkpoint_id,evidencia_id,tipo_relacion)
SELECT c.id,e.id,'AVANCE_APLICADO_C2_NO_CIERRE'
FROM saly.checkpoints_investigacion c JOIN saly.unidades_investigacion u ON u.id=c.unidad_id JOIN saly.evidencias e ON e.codigo='SALY-EVD-LEG-05-C2-AVANCE-20261020'
WHERE u.codigo='SALY-LEG-05' AND c.codigo='C2';
UPDATE saly.checkpoints_investigacion c SET estado='EN_CURSO',
  nota_revision='Análisis C2 de 4 variantes empresariales aplicado, evidencia registrada; falta empleador concreto, posición SBS/registro, contratos validados, costos y contraste C3. Sin dictamen PASS ni APTO.',
  actualizado_en=now()
FROM saly.unidades_investigacion u WHERE c.unidad_id=u.id AND u.codigo='SALY-LEG-05' AND c.codigo='C2' AND c.estado='PENDIENTE';
UPDATE saly.escenarios s
SET parametros=jsonb_set(s.parametros,'{evaluacion_legal,analisis_c2_preliminar}',r.payload,true),updated_at=now()
FROM (VALUES
('SALY-ESC-011','{"escenario":"SALY-ESC-011","modelo":"A","nombre":"Empresa prestamista y SALY SaaS","funds":"CAPITAL_PROPIO_EMPRESA -> DESEMBOLSO_INSTRUCCION_EMPLEADOR -> TRABAJADOR","origin":"EMPLEADOR","creditor":"EMPLEADOR","collector":"EMPLEADOR (planilla) con SALY tecnologia","saly":"SaaS licencia, motor, expediente, onboarding, instruccion bancaria sin custodiar recursos","income":{"employer":"intereses o cargos crediticios solo si proceden","saly":"licencia y servicios SaaS"},"operational_requirements":["Aprobacion politica de prestamos del empleador y facultades societarias","Prestamo trabajador-empresa; consentimiento informado y autorizacion de descuentos dentro de limites","Fondos y titulos crediticios a nombre de empresa; cuenta bancaria empleador o agente de pagos autorizado","Contrato de servicio SALY sin simulacion de que SALY sea acreedor; datos personales y responsabilidades","Clasificar con SBS si actividad interna accesoria o ''dedicada'' a prestamos registrados, segun operativa real"],"legal_position":"FIGURA_CIVIL_PLAUSIBLE_CONDICIONADA_A_CLASIFICACION_DE_ACTIVIDAD_Y_PLANILLA","permitted_without_fund":"NO_REQUIERE_FONDO_POR_SU_SOLO_USO_DE_CAJA","registration":"NO_DETERMINADO_ESPONSABILIDAD_REAL","tax":"Articulo 26 solo condicion especifica adelanto sueldo hasta UIT, no todo prestamo personal, interest real e IGV SaaS requieren tributacion por actor","fallback":"Analizar C o D si actividad interna constituye prestamista regulado que empleador no acepta","complexity":"MENOR_OPERATIVA_POTENCIAL_SIN_CESION","estado":"ANALISIS_C2_PRELIMINAR_SIN_APROBACION","legal_approval":false,"checkpoint":"SALY-LEG-05/C2","source_evidence":"SALY-EVD-LEG-05-C2-AVANCE-20261020"}'::jsonb),
('SALY-ESC-012','{"escenario":"SALY-ESC-012","modelo":"B","nombre":"Bolsa empleador administrada por SALY bajo mandato","funds":"CAPITAL_PROPIO_EMPRESA -> CUENTA_DIFERENCIADA -> DESEMBOLSO_TRABAJADOR","origin":"EMPLEADOR","creditor":"EMPLEADOR","collector":"EMPLEADOR_COBRANZA_PLANILLA","saly":"SaaS + mandato operacional, potencial custodia o pago por cuenta ajena","income":{"employer":"credito trabajador","saly":"tecnologia y administracion"},"operational_requirements":["Precisar nombre legal de cuenta, propiedad, segregacion y disponibilidad","Acreditar mandato y responsabilidades si SALY opera instrumentos bancarios, custodia y administracion","Separar instruccion tecnica y disposicion de recursos ajenos","Mismas obligaciones laborales y SBS potenciales del prestamista empleador"],"legal_position":"CONDICIONADO_POR_REGIMEN_DE_GESTION_DE_DINERO_DE_TERCEROS","registration":"NO_DETERMINADO_CUSTODIA_Y_PRESTAMOS","tax":"Servicios adicionales de mandato, IGV, posibles cargos bancarios; no atribuir rendimientos a SALY por administrar caja","fallback":"Mantener A con cuenta empleador y SALY solo instrucciones validadas","complexity":"MAS_ALTA_POR_GESTION_DE_DINERO","estado":"ANALISIS_C2_PRELIMINAR_SIN_APROBACION","legal_approval":false,"checkpoint":"SALY-LEG-05/C2","source_evidence":"SALY-EVD-LEG-05-C2-AVANCE-20261020"}'::jsonb),
('SALY-ESC-013','{"escenario":"SALY-ESC-013","modelo":"C","nombre":"SALY presta y cede contemporaneamente a empleador","funds":"EMPRESA COMPRA CRÉDITO AL NACER, SALY ORIGINA PRÉSTAMO","origin":"SALY","creditor":"EMPLEADOR DESPUES DE CESION VALIDA","collector":"EMPRESA PLANILLA O SALY COMO SERVICER","saly":"Originacion de credito y cesion, software y administracion","income":{"employer":"recuperacion cartera y rendimiento comprado","saly":"precio cesion, costos originacion/servicing"},"operational_requirements":["Contrato de credito SALY-trabajador, contrato marco cesion futura por escrito","Aceptacion/comunicacion fehaciente de cesion y trazabilidad de titularidad exacta","Demostrar SALY propietaria inicial antes de ceder y cesionario empleador con potestades","Evaluar registro SBS de SALY prestamista habitual y comprador empleador separado","Precio, descuento, riesgo de incobrabilidad, recompra y contabilidad"],"legal_position":"CESION_CIVIL_PLAUSIBLE_SIN_SAFI_PERO_CON_FORMALIDADES_Y_CLASIFICACION_DE_ACTIVIDAD","registration":"NO_DETERMINADO_POR_DOS_ACTORES","tax":"Ingreso por cesion y ganancia de cartera son distintos al SaaS; no asumir neutralidad del IGV de todos conceptos","fallback":"Si empresa no quiere comprar credito/cesiones frecuentes, elegir A o D","complexity":"ALTA_CESION_POR_CREDITO","estado":"ANALISIS_C2_PRELIMINAR_SIN_APROBACION","legal_approval":false,"checkpoint":"SALY-LEG-05/C2","source_evidence":"SALY-EVD-LEG-05-C2-AVANCE-20261020"}'::jsonb),
('SALY-ESC-014','{"escenario":"SALY-ESC-014","modelo":"D","nombre":"Empresa otorga linea revolvente a SALY; SALY presta","funds":"EMPRESA PRESTA A SALY -> SALY DESEMBOLSA -> TRABAJADOR","origin":"SALY","creditor":"SALY","collector":"EMPLEADOR POR CONVENIO PLANILLA A FAVOR SALY","saly":"Prestamista al trabajador y gestor","income":{"employer":"rendimiento linea empresaria SALY","saly":"intereses/cargos de trabajador netos de fondeo"},"operational_requirements":["Prestamo empresa-SALY y contrato por separado SALY-trabajador","Evaluar si empresa se dedica realmente a prestar dinero aunque receptor sea una sola entidad","Registro SBS correspondiente a SALY si actividad de prestamos le es aplicable","Lineas circulantes limites, vencimientos, cartera, inversion en riesgo, garantia","Descuento por planilla con autorizacion laboral"],"legal_position":"DOS_MUTUOS_POSIBLES_CON_RIESGO_REGULATORIO_Y_FINANCIERO_EN_AMBOS_EXTREMOS","registration":"NO_DETERMINADO_AMBOS_PRESTAMISTAS","tax":"Intereses de linea empresa-SALY y margen a trabajador; no aplicar la excepcion 1 UIT del trabajador al prestamo B2B","fallback":"Si registro empresarial o doble carga excesiva, preferir A o comprador fondo E","complexity":"MAYOR_RIESGO_SALY","estado":"ANALISIS_C2_PRELIMINAR_SIN_APROBACION","legal_approval":false,"checkpoint":"SALY-LEG-05/C2","source_evidence":"SALY-EVD-LEG-05-C2-AVANCE-20261020"}'::jsonb)
) AS r(codigo,payload)
WHERE s.codigo=r.codigo AND s.estado='BORRADOR' AND s.parametros->>'familia'='MODELOS_FONDEO_TRIBUTOS';
DO $verify$ BEGIN
 IF (SELECT count(*) FROM saly.escenarios WHERE codigo IN ('SALY-ESC-011','SALY-ESC-012','SALY-ESC-013','SALY-ESC-014') AND parametros->'evaluacion_legal'->'analisis_c2_preliminar'->>'legal_approval'='false' AND parametros->'evaluacion_legal'->>'dictamen_final' IS NULL AND parametros->'validacion'->>'legal'='PENDIENTE')<>4 THEN
  RAISE EXCEPTION 'BLOCK_SALY_APPLIED_MATRIX_READBACK'; END IF;
 IF (SELECT count(*) FROM saly.checkpoints_investigacion c JOIN saly.unidades_investigacion u ON u.id=c.unidad_id WHERE u.codigo='SALY-LEG-05' AND c.codigo='C2' AND c.estado='EN_CURSO' AND c.dictamen_revision IS NULL AND c.evidencia_principal_id IS NULL)<>1 THEN RAISE EXCEPTION 'BLOCK_SALY_C2_NOT_IN_PROGRESS'; END IF;
 IF (SELECT count(*) FROM saly.checkpoint_evidencias ce JOIN saly.evidencias e ON e.id=ce.evidencia_id WHERE e.codigo='SALY-EVD-LEG-05-C2-AVANCE-20261020')<>1 THEN RAISE EXCEPTION 'BLOCK_SALY_C2_LINK'; END IF;
 IF (SELECT count(*) FROM saly.checkpoints_investigacion c JOIN saly.unidades_investigacion u ON u.id=c.unidad_id JOIN saly.programas_investigacion p ON p.id=u.programa_id WHERE p.codigo='SALY_FONDEO_LEGAL' AND c.estado='DONE')<>5 THEN RAISE EXCEPTION 'BLOCK_SALY_DONE_COUNT'; END IF;
END $verify$;
COMMIT;